    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seeds=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==5]
    for r,c in seeds:
        rr,cc=r+1,c-1
        while rr<h and cc>=0 and grid[rr][cc]!=0:
            out[rr][cc]=5
            rr+=1; cc-=1
